// Crossref metadata is a discovery lead, never proof of a paper's factual claims.
const topics = [
 { topic: 'Data-centre electricity and grid demand', query: 'data centre electricity demand power grids' },
 { topic: 'Water use and cooling', query: 'data centre water consumption liquid cooling' },
 { topic: 'Critical minerals and supply chains', query: 'artificial intelligence data centres copper critical minerals supply chains' },
 { topic: 'Frontier AI and hypothetical superintelligence', query: 'frontier artificial intelligence compute scaling safety superintelligence' }
];
const fromDate = (new Date().getUTCFullYear() - 1) + '-01-01';
return topics.map(t => ({json: {
  topic: t.topic,
  url: 'https://api.crossref.org/works?query.bibliographic=' + encodeURIComponent(t.query) +
    '&rows=8&sort=published&order=desc&filter=from-pub-date:' + fromDate +
    '&select=DOI,title,publisher,published,URL,abstract,type',
  review_state: 'metadata_search_only'
}}));

// Treat HTTP responses and bibliographic fields as untrusted research leads.
const queries = $('Define Source Queries').all();
const seen = new Set();
const results = [];
const clean = v => String(v ?? '').replace(/<[^>]*>/g, ' ').replace(/[\r\n\t]+/g, ' ').replace(/\s+/g, ' ').trim();
for (let i = 0; i < $input.all().length; i++) {
  const response = $input.all()[i].json;
  const topic = queries[i]?.json?.topic || 'Unassigned research topic';
  const entries = response?.message?.items;
  if (!Array.isArray(entries)) continue;
  for (const record of entries) {
    const doi = clean(record.DOI).toLowerCase();
    if (!/^10\.\d{4,9}\/\S+$/i.test(doi) || seen.has(doi)) continue;
    seen.add(doi);
    const dateParts = record.published?.['date-parts']?.[0];
    const date = Array.isArray(dateParts) && Number.isInteger(dateParts[0])
      ? [dateParts[0], String(dateParts[1] || 1).padStart(2,'0'), String(dateParts[2] || 1).padStart(2,'0')].join('-')
      : 'date not supplied';
    results.push({json:{
      topic,
      title: clean(record.title?.[0]).slice(0, 220) || 'Title not supplied',
      doi,
      doi_url: 'https://doi.org/' + encodeURI(doi),
      publisher: clean(record.publisher).slice(0, 100),
      published: date,
      item_type: clean(record.type),
      abstract_excerpt: clean(record.abstract).slice(0, 260),
      retrieved_utc: new Date().toISOString(),
      source: 'Crossref registration metadata',
      review_status: 'UNVERIFIED - read and corroborate primary source before citation'
    }});
  }
}
return results.slice(0, 32);

const records = $input.all().map(i => i.json);
const generatedAt = new Date().toISOString();
const lines = [
 '# AI Physical Limits - Evidence Review Queue',
 'Generated: ' + generatedAt,
 '',
 'Status: HUMAN REVIEW REQUIRED. Crossref registration records are research leads, not independent verification.',
 'Never revise the public white paper based solely on this packet.',
 '',
 'Research leads: ' + records.length, ''
];
for (const topic of [...new Set(records.map(r => r.topic))]) {
  lines.push('## ' + topic, '');
  for (const r of records.filter(x => x.topic === topic)) {
    lines.push('- ' + r.title + ' (' + r.published + ')');
    lines.push('  DOI: ' + r.doi_url);
    lines.push('  Publisher: ' + (r.publisher || 'not supplied'));
    lines.push('  Review: ' + r.review_status);
  }
  lines.push('');
}
lines.push('Editorial gate: retrieve and read original work, check methods, publication and event dates, population, uncertainties, corrections, competing evidence, and primary institutional releases. Record reviewer name, decision, version and access date before publication.');
lines.push('Superintelligence: treat hypothetical AGI/ASI pathways as assumptions, never observed capabilities or dated predictions.');
return [{json:{generated_utc: generatedAt, lead_count: records.length, approval_state:'awaiting_human_review', markdown:lines.join('\n')}}];
